-- 0001_initial.sql
-- Initial schema for the Data Intelligence & Analysis Platform.
-- Written for PostgreSQL (Neon). IDs are UUIDs generated by the application.
-- The test runner translates this file to SQLite automatically (see app/migrate.py).

-- ============================================================ USERS & AUTH
CREATE TABLE IF NOT EXISTS users (
    id UUID PRIMARY KEY,
    email VARCHAR(320) NOT NULL,
    display_name VARCHAR(200) NOT NULL DEFAULT '',
    password_hash VARCHAR(500),
    auth_provider VARCHAR(50) NOT NULL DEFAULT 'password',
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    email_verified BOOLEAN NOT NULL DEFAULT FALSE,
    settings_json JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_login_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_users_email ON users (email);

CREATE TABLE IF NOT EXISTS sessions (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash VARCHAR(128) NOT NULL,
    user_agent VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_sessions_token ON sessions (token_hash);
CREATE INDEX IF NOT EXISTS ix_sessions_user ON sessions (user_id);

-- Single-use tokens for password reset and (future) magic-link sign-in.
CREATE TABLE IF NOT EXISTS auth_tokens (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    purpose VARCHAR(30) NOT NULL CHECK (purpose IN ('password_reset', 'magic_link', 'email_verify')),
    token_hash VARCHAR(128) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ NOT NULL,
    used_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_auth_tokens_hash ON auth_tokens (token_hash);

-- ============================================================ PROJECTS
CREATE TABLE IF NOT EXISTS projects (
    id UUID PRIMARY KEY,
    owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name VARCHAR(200) NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    industry VARCHAR(200) NOT NULL DEFAULT '',
    geography VARCHAR(200) NOT NULL DEFAULT '',
    time_period VARCHAR(200) NOT NULL DEFAULT '',
    business_objective TEXT NOT NULL DEFAULT '',
    focus_entity VARCHAR(200) NOT NULL DEFAULT '',
    learning_objectives_json JSONB,
    is_demo BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_projects_owner ON projects (owner_id);

CREATE TABLE IF NOT EXISTS project_members (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role VARCHAR(20) NOT NULL DEFAULT 'owner' CHECK (role IN ('owner', 'editor', 'viewer')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_project_members ON project_members (project_id, user_id);
CREATE INDEX IF NOT EXISTS ix_project_members_user ON project_members (user_id);

-- ============================================================ SOURCES
CREATE TABLE IF NOT EXISTS files (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    uploaded_by UUID REFERENCES users(id) ON DELETE SET NULL,
    original_name VARCHAR(500) NOT NULL,
    safe_name VARCHAR(500) NOT NULL,
    file_type VARCHAR(20) NOT NULL,
    mime_type VARCHAR(200) NOT NULL DEFAULT '',
    size_bytes BIGINT NOT NULL DEFAULT 0,
    sha256 VARCHAR(64) NOT NULL DEFAULT '',
    storage_key VARCHAR(1000) NOT NULL,
    source_role VARCHAR(40) NOT NULL DEFAULT 'auto',
    period_label VARCHAR(100) NOT NULL DEFAULT '',
    status VARCHAR(20) NOT NULL DEFAULT 'uploaded'
        CHECK (status IN ('uploaded', 'processing', 'processed', 'partial', 'failed')),
    extraction_json JSONB,
    error_json JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_files_project ON files (project_id);

-- Text segments extracted from documents, with page/slide/section locators.
CREATE TABLE IF NOT EXISTS document_chunks (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    file_id UUID NOT NULL REFERENCES files(id) ON DELETE CASCADE,
    seq INTEGER NOT NULL,
    kind VARCHAR(30) NOT NULL DEFAULT 'paragraph',
    heading TEXT NOT NULL DEFAULT '',
    text TEXT NOT NULL,
    locator_json JSONB,
    is_approximate BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_chunks_file ON document_chunks (file_id);
CREATE INDEX IF NOT EXISTS ix_chunks_project ON document_chunks (project_id);

CREATE TABLE IF NOT EXISTS datasets (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    file_id UUID NOT NULL REFERENCES files(id) ON DELETE CASCADE,
    name VARCHAR(500) NOT NULL,
    origin VARCHAR(40) NOT NULL DEFAULT 'sheet',
    locator_json JSONB,
    row_count INTEGER NOT NULL DEFAULT 0,
    column_count INTEGER NOT NULL DEFAULT 0,
    is_approximate BOOLEAN NOT NULL DEFAULT FALSE,
    normalized_storage_key VARCHAR(1000),
    profile_json JSONB,
    transformations_json JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_datasets_project ON datasets (project_id);
CREATE INDEX IF NOT EXISTS ix_datasets_file ON datasets (file_id);

CREATE TABLE IF NOT EXISTS dataset_columns (
    id UUID PRIMARY KEY,
    dataset_id UUID NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,
    position INTEGER NOT NULL,
    original_name VARCHAR(500) NOT NULL,
    normalized_name VARCHAR(500) NOT NULL,
    data_type VARCHAR(30) NOT NULL,
    semantic_role VARCHAR(50) NOT NULL DEFAULT 'unknown',
    unit VARCHAR(30) NOT NULL DEFAULT '',
    missing_count INTEGER NOT NULL DEFAULT 0,
    distinct_count INTEGER NOT NULL DEFAULT 0,
    stats_json JSONB
);
CREATE INDEX IF NOT EXISTS ix_dataset_columns_dataset ON dataset_columns (dataset_id);

CREATE TABLE IF NOT EXISTS data_quality_issues (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    file_id UUID REFERENCES files(id) ON DELETE CASCADE,
    dataset_id UUID REFERENCES datasets(id) ON DELETE CASCADE,
    issue_type VARCHAR(50) NOT NULL,
    field VARCHAR(500) NOT NULL DEFAULT '',
    severity VARCHAR(10) NOT NULL CHECK (severity IN ('high', 'medium', 'low')),
    description TEXT NOT NULL,
    suggested_resolution TEXT NOT NULL DEFAULT '',
    locator_json JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_dq_project ON data_quality_issues (project_id);

-- URLs and other external references attached to a project (optional external research).
CREATE TABLE IF NOT EXISTS research_sources (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    kind VARCHAR(20) NOT NULL DEFAULT 'url' CHECK (kind IN ('url', 'citation', 'note')),
    url VARCHAR(2000) NOT NULL DEFAULT '',
    title VARCHAR(500) NOT NULL DEFAULT '',
    notes TEXT NOT NULL DEFAULT '',
    fetch_status VARCHAR(20) NOT NULL DEFAULT 'not_fetched',
    file_id UUID REFERENCES files(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_research_sources_project ON research_sources (project_id);

-- ============================================================ ANALYSIS
CREATE TABLE IF NOT EXISTS analysis_runs (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    mode VARCHAR(20) NOT NULL CHECK (mode IN ('quick', 'deep', 'research')),
    auto_discover BOOLEAN NOT NULL DEFAULT TRUE,
    status VARCHAR(20) NOT NULL DEFAULT 'queued'
        CHECK (status IN ('queued', 'running', 'completed', 'partial', 'failed')),
    progress INTEGER NOT NULL DEFAULT 0,
    stage VARCHAR(100) NOT NULL DEFAULT '',
    file_ids_json JSONB,
    summary_json JSONB,
    result_json JSONB,
    error_json JSONB,
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_runs_project ON analysis_runs (project_id, created_at);

CREATE TABLE IF NOT EXISTS analysis_questions (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    question TEXT NOT NULL,
    origin VARCHAR(20) NOT NULL DEFAULT 'user' CHECK (origin IN ('user', 'auto')),
    intents_json JSONB,
    answer_json JSONB,
    status VARCHAR(20) NOT NULL DEFAULT 'pending',
    position INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS ix_questions_run ON analysis_questions (run_id);

CREATE TABLE IF NOT EXISTS findings (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    category VARCHAR(40) NOT NULL,
    title TEXT NOT NULL,
    fact TEXT NOT NULL,
    interpretation TEXT NOT NULL DEFAULT '',
    implication TEXT NOT NULL DEFAULT '',
    hypothesis TEXT NOT NULL DEFAULT '',
    validation TEXT NOT NULL DEFAULT '',
    confidence VARCHAR(10) NOT NULL CHECK (confidence IN ('high', 'medium', 'low')),
    is_approximate BOOLEAN NOT NULL DEFAULT FALSE,
    score DOUBLE PRECISION NOT NULL DEFAULT 0,
    rank INTEGER NOT NULL DEFAULT 0,
    tags_json JSONB,
    chart_json JSONB,
    details_json JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_findings_run ON findings (run_id, rank);
CREATE INDEX IF NOT EXISTS ix_findings_project ON findings (project_id);

CREATE TABLE IF NOT EXISTS finding_evidence (
    id UUID PRIMARY KEY,
    finding_id UUID NOT NULL REFERENCES findings(id) ON DELETE CASCADE,
    file_id UUID REFERENCES files(id) ON DELETE SET NULL,
    dataset_id UUID REFERENCES datasets(id) ON DELETE SET NULL,
    chunk_id UUID REFERENCES document_chunks(id) ON DELETE SET NULL,
    source_label TEXT NOT NULL DEFAULT '',
    locator_json JSONB,
    excerpt TEXT NOT NULL DEFAULT '',
    values_json JSONB,
    is_approximate BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX IF NOT EXISTS ix_evidence_finding ON finding_evidence (finding_id);

CREATE TABLE IF NOT EXISTS trends (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,
    finding_id UUID REFERENCES findings(id) ON DELETE CASCADE,
    dataset_id UUID REFERENCES datasets(id) ON DELETE SET NULL,
    measure VARCHAR(500) NOT NULL,
    dimension VARCHAR(500) NOT NULL DEFAULT '',
    dimension_value VARCHAR(500) NOT NULL DEFAULT '',
    direction VARCHAR(20) NOT NULL,
    start_period VARCHAR(50) NOT NULL DEFAULT '',
    end_period VARCHAR(50) NOT NULL DEFAULT '',
    start_value DOUBLE PRECISION,
    end_value DOUBLE PRECISION,
    abs_change DOUBLE PRECISION,
    pct_change DOUBLE PRECISION,
    cagr DOUBLE PRECISION,
    slope DOUBLE PRECISION,
    r_squared DOUBLE PRECISION,
    acceleration VARCHAR(20) NOT NULL DEFAULT '',
    series_json JSONB
);
CREATE INDEX IF NOT EXISTS ix_trends_run ON trends (run_id);

CREATE TABLE IF NOT EXISTS comparisons (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,
    finding_id UUID REFERENCES findings(id) ON DELETE CASCADE,
    comparison_type VARCHAR(30) NOT NULL,
    subject_a VARCHAR(500) NOT NULL,
    subject_b VARCHAR(500) NOT NULL,
    measure VARCHAR(500) NOT NULL DEFAULT '',
    value_a DOUBLE PRECISION,
    value_b DOUBLE PRECISION,
    difference DOUBLE PRECISION,
    pct_difference DOUBLE PRECISION,
    details_json JSONB
);
CREATE INDEX IF NOT EXISTS ix_comparisons_run ON comparisons (run_id);

CREATE TABLE IF NOT EXISTS gaps (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,
    finding_id UUID REFERENCES findings(id) ON DELETE CASCADE,
    gap_type VARCHAR(30) NOT NULL,
    gap TEXT NOT NULL,
    evidence TEXT NOT NULL DEFAULT '',
    why_it_matters TEXT NOT NULL DEFAULT '',
    significance VARCHAR(10) NOT NULL DEFAULT 'medium',
    missing_information TEXT NOT NULL DEFAULT '',
    recommended_investigation TEXT NOT NULL DEFAULT '',
    potential_action TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS ix_gaps_run ON gaps (run_id);

CREATE TABLE IF NOT EXISTS opportunities (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,
    finding_id UUID REFERENCES findings(id) ON DELETE CASCADE,
    subject VARCHAR(500) NOT NULL,
    classification VARCHAR(50) NOT NULL,
    rationale TEXT NOT NULL DEFAULT '',
    potential_usp TEXT NOT NULL DEFAULT '',
    competition_level VARCHAR(20) NOT NULL DEFAULT '',
    demand_indicators TEXT NOT NULL DEFAULT '',
    risks TEXT NOT NULL DEFAULT '',
    needs_validation TEXT NOT NULL DEFAULT '',
    confidence VARCHAR(10) NOT NULL DEFAULT 'low',
    metrics_json JSONB
);
CREATE INDEX IF NOT EXISTS ix_opportunities_run ON opportunities (run_id);

CREATE TABLE IF NOT EXISTS risks (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,
    finding_id UUID REFERENCES findings(id) ON DELETE CASCADE,
    risk TEXT NOT NULL,
    horizon VARCHAR(20) NOT NULL DEFAULT '',
    likelihood VARCHAR(10) NOT NULL DEFAULT 'medium',
    impact TEXT NOT NULL DEFAULT '',
    mitigation TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS ix_risks_run ON risks (run_id);

CREATE TABLE IF NOT EXISTS recommendations (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,
    finding_id UUID REFERENCES findings(id) ON DELETE CASCADE,
    recommendation TEXT NOT NULL,
    rec_type VARCHAR(30) NOT NULL DEFAULT 'action',
    priority VARCHAR(10) NOT NULL DEFAULT 'medium',
    rationale TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS ix_recommendations_run ON recommendations (run_id);

CREATE TABLE IF NOT EXISTS research_questions (
    id UUID PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    finding_id UUID REFERENCES findings(id) ON DELETE SET NULL,
    question TEXT NOT NULL,
    question_type VARCHAR(30) NOT NULL DEFAULT 'research',
    rationale TEXT NOT NULL DEFAULT '',
    methodologies_json JSONB,
    data_needed TEXT NOT NULL DEFAULT '',
    priority VARCHAR(10) NOT NULL DEFAULT 'medium'
);
CREATE INDEX IF NOT EXISTS ix_research_questions_run ON research_questions (run_id);

-- Ask Your Data conversation history.
CREATE TABLE IF NOT EXISTS ask_messages (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    question TEXT NOT NULL,
    answer_json JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_ask_project ON ask_messages (project_id, created_at);

-- ============================================================ REPORTS
CREATE TABLE IF NOT EXISTS reports (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    run_id UUID REFERENCES analysis_runs(id) ON DELETE SET NULL,
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    title VARCHAR(500) NOT NULL,
    content_json JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_reports_project ON reports (project_id);

CREATE TABLE IF NOT EXISTS report_exports (
    id UUID PRIMARY KEY,
    report_id UUID NOT NULL REFERENCES reports(id) ON DELETE CASCADE,
    format VARCHAR(10) NOT NULL CHECK (format IN ('pdf', 'docx', 'xlsx')),
    storage_key VARCHAR(1000) NOT NULL,
    size_bytes BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_report_exports_report ON report_exports (report_id);

-- ============================================================ AUDIT
CREATE TABLE IF NOT EXISTS audit_logs (
    id UUID PRIMARY KEY,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    project_id UUID,
    action VARCHAR(100) NOT NULL,
    target_type VARCHAR(50) NOT NULL DEFAULT '',
    target_id VARCHAR(100) NOT NULL DEFAULT '',
    details_json JSONB,
    ip_address VARCHAR(100) NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_audit_user ON audit_logs (user_id, created_at);
CREATE INDEX IF NOT EXISTS ix_audit_project ON audit_logs (project_id);
